// Imports

if ($('.js-component-modifier').length) {
    $('.js-component-modifier').on('change', function () {
        let modifier = $(this).val();
        let target = $(this).attr('data-target');

        if ($(this).prop('checked') == true) {
            if (target == '.c-hero-article' || target == '.c-hero-simple') {
                $(target).addClass(modifier);
            } else {
                $(this).closest('.o-wrapper').find(target).addClass(modifier);
            }
        }
        else if ($(this).prop('checked') == false) {
            if (target == '.c-hero-article' || target == '.c-hero-simple') {
                $(target).removeClass(modifier);
            } else {
                $(this).closest('.o-wrapper').find(target).removeClass(modifier);
            }
        }
    });
}

if ($('.c-components-index').length) {
    let indexButton = $('.js-components-index-button');
    let indexContent = $('.js-components-index-content');
    
    indexButton.on('click', function () {
        indexButton.toggleClass('is-active');
        indexContent.slideToggle();

        if (indexButton.hasClass('is-active')) {
            indexButton.attr('aria-expanded','true')
            trapFocus(indexContent);
        } else {
            indexButton.attr('aria-expanded', 'false')
            unTrapFocus(indexButton);
        }
    });

    $(document).on('keydown', function (e) {
        if (e.key == 'Escape') {
            if (indexButton.hasClass('is-active')) {
                indexButton.attr('aria-expanded', 'false')
                unTrapFocus(indexButton);
                indexButton.removeClass('is-active');
                indexContent.slideUp();
            }
        }
    });

    $('.c-components-index__list').empty();
    let sections = $('.c-section[id]');

    sections.each(function () {
        let textSection = $(this).find('.c-section__title').first().text();
        let hrefSection = $(this).attr('id');
        $('.c-components-index__list').append('<li class="c-components-index__item"><a class="c-components-index__link c-button-line c-button-line--purple" href="#' + hrefSection + '">' + textSection+'</a></li>')
    });
}